window.products.push({"id":237170,"name":"JAPAN MUSEUM, Katsushika Hokusai, Fine Wind Clear Weather Red Fuji | Japanese Fine Art | Ukiyo-e Artwork | Genuine Hand-printed Woodblock Print | Japa","category":"homeandappliances","retail price":499.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/715gsX+viEL._AC_SL1500_.jpg","description":"Fine Wind, Clear Morning, also known as Red Fuji, is a woodblock print by Japanese artist Hokusai, part of his Thirty-six Views of Mount Fuji series. This artwork is 390mm X 260mm in size and was reprinted by hand using the highest quality Japanese WASHI paper, one color at a time, with a Japanese Bamboo Leaf Baren in hand, by a traditional craftsman who has inherited techniques from the Edo period. This is a genuine hand-printed woodblock print.","images":["https://m.media-amazon.com/images/I/715gsX+viEL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"ＪＡＰＡＮ＼ＭＵＳＥＵＭ","source_asin":"B0BLJG9CG9","category_path":"Home & Kitchen"},"sku":"BM-237170","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BLJG9CG9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BLJG9CG9","price_pending":true,"merchant_ready":false});
